internal fun translateInsight(language: AppLanguage, sourceChinese: String): String? {
    val item = insightTranslations[sourceChinese] ?: return null
    return when (language) {
        AppLanguage.CHINESE -> sourceChinese
        AppLanguage.ENGLISH -> item.en
        AppLanguage.FRENCH -> item.fr
        AppLanguage.ARABIC -> item.ar
    }
}
